'use client'

import * as React from 'react'

import { type CueKind, type CueName, type HapticName, describeCue } from './cue-catalogue'
import { type JuiceLevel, allowsCue } from './juice'
import { fireHaptic } from './haptics'
import { createOsMuteWatcher } from './os-mute'
import { type SoundAdapter, createHtmlAudioAdapter } from './sound-adapter'

/**
 * GameFeelProvider: juice, cue playback and haptics as one provider (BDS-030,
 * REQ-039 to REQ-045).
 *
 * It plays nothing itself. It decides whether a named cue is allowed through
 * (mute, haptics-off and juice all gate independently), hands an allowed sfx
 * cue to a sound adapter and an allowed haptic cue to `navigator.vibrate`,
 * and records what it handed over. No asset files exist yet (GSUI-38), so
 * today "playing" a cue is that recording: the intent event fired, in order,
 * nothing more.
 */

export interface GameFeelCueEvent {
  name: string
  kind: CueKind
}

export interface GameFeelValue {
  juice: JuiceLevel
  /** Explicit mute ORed with the best-effort OS silent-switch signal. */
  muted: boolean
  hapticsOff: boolean
  /** Hands a cue to the runtime. Gated by juice, then by mute or haptics-off. */
  cue: (name: CueName, kind: CueKind) => void
}

const DEFAULT_FEEL: GameFeelValue = {
  juice: 'standard',
  muted: false,
  hapticsOff: false,
  // No provider mounted: degrade to a no-op rather than throwing, matching
  // the rest of the library (REQ-006). There is nowhere to record a cue and
  // nothing waiting to hear about one.
  cue: () => {},
}

const GameFeelContext = React.createContext<GameFeelValue>(DEFAULT_FEEL)

export function useGameFeel(): GameFeelValue {
  return React.useContext(GameFeelContext)
}

export interface GameFeelProviderProps {
  children: React.ReactNode
  /**
   * The host's own mute switch (the lab's `?mute=`, or a customer's setting).
   * Combined with the OS signal by OR: either can silence sound, neither can
   * force it back on.
   */
  muted?: boolean
  hapticsOff?: boolean
  juice?: JuiceLevel
  /** Defaults to an HTMLAudio-backed stub; GSUI-38 supplies a real adapter. */
  sound?: SoundAdapter
  /**
   * Fired once per cue the runtime let through, after every gate. This is the
   * test/debug and host-integration hook: the runtime performs nothing
   * itself (BDS-030), so this is how a host, or a test, observes what would
   * have played. Not analytics (REQ-005): it carries no player intent, only
   * that a cue fired.
   */
  onCue?: (event: GameFeelCueEvent) => void
}

export function GameFeelProvider({
  children,
  muted: explicitMuted = false,
  hapticsOff = false,
  juice = 'standard',
  sound,
  onCue,
}: GameFeelProviderProps) {
  const soundAdapter = sound ?? defaultSoundAdapter

  const [osMuted, setOsMuted] = React.useState(false)
  React.useEffect(() => {
    const watcher = createOsMuteWatcher(setOsMuted)
    return () => watcher.dispose()
  }, [])

  const muted = explicitMuted || osMuted

  // The attribute contract's provider root. `cues` ships no DOM of its own
  // (docs/attribute-contract.md, "every component names its root"), so this
  // state lives on the document root rather than on a wrapper element the
  // provider would otherwise have to render around `children`.
  React.useEffect(() => {
    const root = document.documentElement
    if (muted) root.setAttribute('data-gs-muted', 'true')
    else root.removeAttribute('data-gs-muted')
    return () => root.removeAttribute('data-gs-muted')
  }, [muted])

  React.useEffect(() => {
    const root = document.documentElement
    if (hapticsOff) root.setAttribute('data-gs-haptics-muted', 'true')
    else root.removeAttribute('data-gs-haptics-muted')
    return () => root.removeAttribute('data-gs-haptics-muted')
  }, [hapticsOff])

  React.useEffect(() => {
    const root = document.documentElement
    root.setAttribute('data-gs-juice', juice)
    return () => root.removeAttribute('data-gs-juice')
  }, [juice])

  const ledger = React.useRef<string[]>([])
  React.useEffect(() => {
    ledger.current = []
    document.documentElement.setAttribute('data-gs-cues', '')
    return () => document.documentElement.removeAttribute('data-gs-cues')
  }, [])

  const record = React.useCallback((entry: string) => {
    ledger.current = [...ledger.current, entry]
    if (typeof document !== 'undefined') {
      document.documentElement.setAttribute('data-gs-cues', ledger.current.join(' '))
    }
  }, [])

  const cue = React.useCallback<GameFeelValue['cue']>(
    (name, kind) => {
      const tier = describeCue(kind, name)?.tier ?? 'standard'
      if (!allowsCue(juice, tier)) return

      if (kind === 'haptic') {
        if (hapticsOff) return
        fireHaptic(name as HapticName)
      } else {
        if (muted) return
        soundAdapter.play(name)
      }

      record(`${kind}:${name}`)
      onCue?.({ name, kind })
    },
    [juice, muted, hapticsOff, soundAdapter, onCue, record],
  )

  const value = React.useMemo<GameFeelValue>(
    () => ({ juice, muted, hapticsOff, cue }),
    [juice, muted, hapticsOff, cue],
  )

  return <GameFeelContext.Provider value={value}>{children}</GameFeelContext.Provider>
}

const defaultSoundAdapter = createHtmlAudioAdapter()

import type { CueTier } from './cue-catalogue'

/**
 * How much celebration the host wants (`data-gs-juice` in the attribute
 * contract). A scalar on one code path (docs/testing-strategy.md): `none` and
 * `maximum` bound it, and the two middle values only narrow what plays
 * between those two ends.
 */
export type JuiceLevel = 'none' | 'reduced' | 'standard' | 'maximum'

const SCALAR: Record<JuiceLevel, number> = { none: 0, reduced: 1, standard: 2, maximum: 3 }

const THRESHOLD: Record<CueTier, number> = { essential: 0, standard: 1, celebration: 2 }

/**
 * Whether a cue of this tier plays at this juice level. `essential` always
 * returns true: juice scales the flourish on top of a state change, never the
 * confirmation of the state change itself. Only mute silences an essential cue.
 */
export function allowsCue(level: JuiceLevel, tier: CueTier): boolean {
  return SCALAR[level] >= THRESHOLD[tier]
}

import type { HapticName } from './cue-catalogue'

/**
 * Vibration patterns in milliseconds, one per haptic intent. No web API
 * exposes "light/medium/heavy" the way a native Taptic Engine does;
 * `navigator.vibrate` is the only cross-browser primitive, so a pattern is
 * the closest approximation available and this is the one place that names
 * the numbers.
 */
const PATTERN: Record<HapticName, number | number[]> = {
  light: 10,
  medium: 20,
  heavy: 35,
  success: [10, 30, 10],
  error: [20, 40, 20],
}

export function canVibrate(): boolean {
  return typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function'
}

/** Fires the pattern for a haptic intent. Returns false wherever the device cannot vibrate. */
export function fireHaptic(name: HapticName): boolean {
  if (!canVibrate()) return false
  return navigator.vibrate(PATTERN[name])
}

/**
 * Best-effort detection of the OS silent switch.
 *
 * There is no web platform API for "the hardware mute switch is on." The one
 * observable signal, on iOS Safari, is that an unlocked `AudioContext` moves
 * to `state: "interrupted"` while the switch is engaged; every other engine
 * simply never reports it. So this can tell the provider "the device says it
 * is silenced," and it can never tell it "sound is definitely allowed." The
 * provider ORs this with the explicit `muted` prop: either can silence sound,
 * neither can force it back on.
 *
 * Deliberately not `prefers-reduced-motion`: that media feature describes
 * motion sensitivity, not sound, and wiring it to mute would silence a player
 * who only asked for stillness.
 */
export interface OsMuteWatcher {
  dispose(): void
}

export function createOsMuteWatcher(onChange: (muted: boolean) => void): OsMuteWatcher {
  if (typeof window === 'undefined' || typeof window.AudioContext === 'undefined') {
    return { dispose: () => {} }
  }

  let ctx: AudioContext
  try {
    ctx = new window.AudioContext()
  } catch {
    return { dispose: () => {} }
  }

  const handleChange = () => onChange(ctx.state === 'interrupted')
  ctx.addEventListener('statechange', handleChange)

  return {
    dispose: () => {
      ctx.removeEventListener('statechange', handleChange)
      void ctx.close().catch(() => {})
    },
  }
}

/**
 * How an allowed cue is actually made audible. Behind an interface because no
 * asset exists yet (GSUI-38 attaches a real file to each name): today
 * "playing" a cue never touches the network or the disk, which is what keeps
 * REQ-001 true once this stops being a stub.
 *
 * HTMLAudioElement is the default because it is the element whose playback
 * iOS Safari's hardware silent switch actually silences; a raw WebAudio graph
 * bypasses that switch entirely, which is why os-mute.ts exists as a
 * best-effort backstop rather than the only mechanism.
 */
export interface SoundAdapter {
  play(name: string): void
}

export function createHtmlAudioAdapter(): SoundAdapter {
  return {
    play() {
      // No asset files yet. The caller has already recorded the intent
      // before reaching here; there is nothing to play.
    },
  }
}

export function createWebAudioAdapter(): SoundAdapter {
  return {
    play() {
      // Same stub, kept as a distinct adapter so GSUI-38 can wire a real
      // AudioBufferSourceNode here without re-deciding which of the two
      // honours the silent switch.
    },
  }
}
